SELECT disease_name
FROM disease_involvement
WHERE protein_id = (SELECT protein_id FROM proteins WHERE entry = 'P35499');

SELECT pathway_name  
FROM protein_pathways  
WHERE protein_id = (SELECT protein_id FROM proteins WHERE entry = 'A0AVI4');

SELECT COUNT(*) AS num_proteins  
FROM disease_involvement  
JOIN proteins ON disease_involvement.protein_id = proteins.protein_id;

SELECT ROUND(AVG(binding_sites.position), 2) AS average_binding_sites
FROM binding_sites
WHERE binding_sites.position IS NOT NULL;

SELECT domain_name, COUNT(*) AS count
FROM topological_domains
GROUP BY domain_name;

SELECT COUNT(*) AS total  
FROM mutagenesis  
WHERE COUNT(*) > 10;

SELECT MAX(LENGTH(interaction_type)) AS highest_experiments  
FROM interactions  
WHERE protein_id = (SELECT protein_id FROM proteins WHERE entry = 'P04637');

SELECT description
FROM disease_involvement
WHERE description LIKE '%insulin%';
